import { lcardsLog } from '../../utils/lcards-logging.js';
import { ColorUtils } from '../../core/themes/ColorUtils.js';

// Module-scoped text measurement state (private implementation detail)
let _textMeasureCanvas = null;
let _textMeasureContext = null;
let _textMeasureCache = null;

/**
 * [RendererUtils] Shared renderer utilities - common functionality for all renderers
 * 🛠️ Provides reusable components for gradients, patterns, filters, and effects
 */

export class RendererUtils {


  /**
   * Text measurement utilities using HTML Canvas
   * Static methods for precise text dimension calculations
   */

  /**
   * Get or create cached canvas context for text measurements
   * @private
   * @returns {CanvasRenderingContext2D}
   */
  static _getTextMeasureContext() {
    if (!_textMeasureCanvas) {
      _textMeasureCanvas = document.createElement("canvas");
      _textMeasureContext = _textMeasureCanvas.getContext("2d");
      _textMeasureCache = new Map();
    }

    return _textMeasureContext;
  }

  /**
   * Get the SVG container and its current transformation matrix
   * @param {Element} containerElement - The SVG container element
   * @returns {Object|null} Object with svg element and transformation info
   */
  static _getSvgTransformInfo(containerElement) {
    try {
      const svg = containerElement?.querySelector('svg');
      if (!svg) return null;

      // Get the viewBox and current dimensions
      const viewBox = svg.viewBox.baseVal;
      const rect = svg.getBoundingClientRect();

      // Calculate scale factors
      const scaleX = viewBox.width / rect.width;
      const scaleY = viewBox.height / rect.height;

      return {
        svg,
        viewBox: [viewBox.x, viewBox.y, viewBox.width, viewBox.height],
        screenRect: { width: rect.width, height: rect.height },
        scaleX,
        scaleY,
        // For pixel-to-viewbox conversion
        pixelToViewBox: (pixelSize) => pixelSize * Math.max(scaleX, scaleY)
      };
    } catch (error) {
      lcardsLog.warn('[RendererUtils] ⚠️ Failed to get SVG transform info:', error);
      return null;
    }
  }

  /**
   * Measure text dimensions using canvas context
   * @param {string} text - Text to measure
   * @param {string} font - CSS font string (e.g., "bold 16px Arial")
   * @param {boolean} useCache - Whether to use cached measurements
   * @param {Element} containerElement - SVG container for coordinate transformation
   * @returns {{width: number, height: number, ascent: number, descent: number}}
   */
  static measureText(text, font = "16px Arial", useCache = true, containerElement = null) {
    if (!text) return { width: 0, height: 0, ascent: 0, descent: 0 };

    const cacheKey = `${text}::${font}`;
    const cache = _textMeasureCache;

    if (useCache && cache && cache.has(cacheKey)) {
      const cached = cache.get(cacheKey);

      // Apply coordinate transformation if container provided
      if (containerElement) {
        return this._transformTextMetrics(cached, containerElement);
      }

      return cached;
    }

    const ctx = this._getTextMeasureContext();
    ctx.font = font;
    const metrics = ctx.measureText(text);

    const result = {
      width: metrics.width,
      height: metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent,
      ascent: metrics.actualBoundingBoxAscent,
      descent: metrics.actualBoundingBoxDescent,
      actualLeft: metrics.actualBoundingBoxLeft || 0,
      actualRight: metrics.actualBoundingBoxRight || metrics.width,
      // Store original pixel values for transformation
      _pixelWidth: metrics.width,
      _pixelHeight: metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent,
      _pixelAscent: metrics.actualBoundingBoxAscent,
      _pixelDescent: metrics.actualBoundingBoxDescent
    };

    if (useCache && cache) {
      cache.set(cacheKey, result);
    }

    // Apply coordinate transformation if container provided
    if (containerElement) {
      return this._transformTextMetrics(result, containerElement);
    }

    return result;
  }

  /**
   * Transform text metrics from pixel space to viewBox coordinate space
   * @private
   * @param {Object} metrics - Original pixel-based metrics
   * @param {Element} containerElement - SVG container for transformation
   * @returns {Object} Transformed metrics in viewBox coordinates
   */
  static _transformTextMetrics(metrics, containerElement) {
    const transformInfo = this._getSvgTransformInfo(containerElement);
    if (!transformInfo) {
      // Fallback to pixel metrics is acceptable - not all contexts have transform info
      lcardsLog.trace('[RendererUtils] No transform info available, using pixel metrics');
      return metrics;
    }

    const { pixelToViewBox } = transformInfo;

    const transformed = {
      ...metrics,
      width: pixelToViewBox(metrics._pixelWidth || metrics.width),
      height: pixelToViewBox(metrics._pixelHeight || metrics.height),
      ascent: pixelToViewBox(metrics._pixelAscent || metrics.ascent),
      descent: pixelToViewBox(metrics._pixelDescent || metrics.descent),
      actualLeft: pixelToViewBox(metrics.actualLeft),
      actualRight: pixelToViewBox(metrics.actualRight)
    };



    return transformed;
  }

  /**
   * Measure multiline text with proper line spacing and coordinate transformation
   * @param {string} text - Multiline text (with \n separators)
   * @param {string} font - CSS font string
   * @param {number} lineHeight - Line height multiplier (default 1.2)
   * @param {boolean} useCache - Whether to use cached measurements
   * @param {Element} containerElement - SVG container for coordinate transformation
   * @returns {{width: number, height: number, lines: Array, lineMetrics: Array, _transformApplied: boolean, _adjustedFontSize: number}}
   */
  static measureMultilineText(text, font = "16px Arial", lineHeight = 1.2, useCache = true, containerElement = null) {
    if (!text) return { width: 0, height: 0, lines: [], lineMetrics: [], _transformApplied: false, _adjustedFontSize: 0 };

    const lines = text.split('\n');
    const lineMetrics = lines.map(line => this.measureText(line, font, useCache, containerElement));

    const maxWidth = Math.max(...lineMetrics.map(m => m.width));
    const fontSize = this._parseFontSize(font);

    // Apply transformation to fontSize if container provided
    let adjustedFontSize = fontSize;
    let adjustedLineHeight = lineHeight;

    if (containerElement) {
      const transformInfo = this._getSvgTransformInfo(containerElement);
      if (transformInfo) {
        adjustedFontSize = transformInfo.pixelToViewBox(fontSize);
        // Line height is a multiplier, so we need to apply it to the transformed font size
        adjustedLineHeight = lineHeight;
      }
    }

    const totalHeight = lines.length > 1
      ? lineMetrics[0].ascent + ((lines.length - 1) * adjustedFontSize * adjustedLineHeight) + lineMetrics[lineMetrics.length - 1].descent
      : lineMetrics[0]?.height || 0;

    return {
      width: maxWidth,
      height: totalHeight,
      lines,
      lineMetrics,
      // Store transform info for debugging
      _transformApplied: !!containerElement,
      _adjustedFontSize: adjustedFontSize
    };
  }

  /**
   * Calculate text bounding box at specific position with proper coordinate transformation
   * @param {string} text - Text content
   * @param {number} x - X position in viewBox coordinates
   * @param {number} y - Y position in viewBox coordinates
   * @param {string} font - CSS font string
   * @param {string} textAnchor - SVG text-anchor value ('start', 'middle', 'end')
   * @param {string} dominantBaseline - SVG dominant-baseline value
   * @param {Element} containerElement - SVG container for coordinate transformation
   * @returns {{left: number, right: number, top: number, bottom: number, width: number, height: number, centerX: number, centerY: number}}
   */
  static getTextBoundingBox(text, x, y, font = "16px Arial", textAnchor = 'start', dominantBaseline = 'auto', containerElement = null) {
    const metrics = this.measureText(text, font, true, containerElement);

    // Adjust for text anchor (x, y are already in viewBox coordinates)
    let left = x;
    if (textAnchor === 'middle') {
      left = x - metrics.width / 2;
    } else if (textAnchor === 'end') {
      left = x - metrics.width;
    }

    // Adjust for baseline (y is already in viewBox coordinates)
    let top = y - metrics.ascent;
    if (dominantBaseline === 'middle' || dominantBaseline === 'central') {
      top = y - metrics.height / 2;
    } else if (dominantBaseline === 'hanging') {
      top = y;
    }

    const bbox = {
      left,
      right: left + metrics.width,
      top,
      bottom: top + metrics.height,
      width: metrics.width,
      height: metrics.height,
      centerX: left + metrics.width / 2,
      centerY: top + metrics.height / 2
    };



    return bbox;
  }

  /**
   * Get attachment points for connecting lines to text with proper coordinate transformation
   * @param {string} text - Text content
   * @param {number} x - X position
   * @param {number} y - Y position
   * @param {string} font - CSS font string
   * @param {string} textAnchor - SVG text-anchor value
   * @param {string} dominantBaseline - SVG dominant-baseline value
   * @param {Element} containerElement - SVG container for coordinate transformation
   * @returns {Object} Object with attachment points (top, bottom, left, right, etc.)
   */
  static getTextAttachmentPoints(text, x, y, font = "16px Arial", textAnchor = 'start', dominantBaseline = 'auto', containerElement = null) {
    const bbox = this.getTextBoundingBox(text, x, y, font, textAnchor, dominantBaseline, containerElement);

    // Calculate padding in viewBox coordinates - don't double-transform
    const transformInfo = this._getSvgTransformInfo(containerElement);
    const basePadding = 4; // Base padding value
    const padding = transformInfo ? transformInfo.pixelToViewBox(basePadding) : basePadding;

    return {
      // Cardinal directions
      top: [bbox.centerX, bbox.top],
      bottom: [bbox.centerX, bbox.bottom],
      left: [bbox.left, bbox.centerY],
      right: [bbox.right, bbox.centerY],
      center: [bbox.centerX, bbox.centerY],

      // Corners
      topLeft: [bbox.left, bbox.top],
      topRight: [bbox.right, bbox.top],
      bottomLeft: [bbox.left, bbox.bottom],
      bottomRight: [bbox.right, bbox.bottom],

      // With padding for visual clearance (properly scaled)
      topPadded: [bbox.centerX, bbox.top - padding],
      bottomPadded: [bbox.centerX, bbox.bottom + padding],
      leftPadded: [bbox.left - padding, bbox.centerY],
      rightPadded: [bbox.right + padding, bbox.centerY]
    };
  }

  /**
   * Parse font size from CSS font string
   * @private
   * @param {string} font - CSS font string
   * @returns {number} Font size in pixels
   */
  static _parseFontSize(font) {
    const match = font.match(/(\d+(?:\.\d+)?)px/);
    return match ? parseFloat(match[1]) : 16;
  }

  /**
   * Build CSS font string from text style object
   * @param {Object} textStyle - Text style configuration
   * @returns {string} CSS font string
   */
  static buildFontString(textStyle) {
    const parts = [];

    if (textStyle.fontStyle && textStyle.fontStyle !== 'normal') {
      parts.push(textStyle.fontStyle);
    }
    if (textStyle.fontWeight && textStyle.fontWeight !== 'normal') {
      parts.push(textStyle.fontWeight);
    }

    parts.push(`${textStyle.fontSize}px`);

    if (textStyle.fontFamily && textStyle.fontFamily !== 'inherit') {
      parts.push(textStyle.fontFamily);
    } else {
      parts.push('Arial, sans-serif');
    }

    return parts.join(' ');
  }

  /**
   * Resolve effective font-family when textStyle uses 'inherit'.
   * Tries: svg element -> container element -> documentElement -> fallback.
   */
  static resolveFontFamily(textStyle, containerElement) {
    if (textStyle.fontFamily && textStyle.fontFamily !== 'inherit') {
      return textStyle.fontFamily;
    }
    try {
      const svg = containerElement?.querySelector?.('svg');
      const target = svg || containerElement || document.documentElement;
      const computed = window.getComputedStyle(target).fontFamily;
      if (computed && computed !== 'inherit') return computed;
    } catch (e) {
      lcardsLog.warn('[RendererUtils] ⚠️ resolveFontFamily failed:', e);
    }
    return 'Arial, sans-serif';
  }

  /**
   * Build a font string adjusted for measurement so canvas uses the ACTUAL on-screen pixel size.
   * Without this, we measure at raw user-unit size (too large when viewBox scales down),
   * leading to overestimated widths and misplaced decorations (e.g., status indicator).
   */
  static buildMeasurementFontString(textStyle, containerElement) {
    // Resolve actual inherited font-family instead of fallback
    const fontFamily = this.resolveFontFamily(textStyle, containerElement);
    const fontStyle = (textStyle.fontStyle && textStyle.fontStyle !== 'normal') ? `${textStyle.fontStyle} ` : '';
    const fontWeight = (textStyle.fontWeight && textStyle.fontWeight !== 'normal') ? `${textStyle.fontWeight} ` : '';

    let adjustedPx = textStyle.fontSize;
    if (containerElement) {
      const transformInfo = this._getSvgTransformInfo(containerElement);
      if (transformInfo) {
        const screenPxPerViewBoxUnit = transformInfo.screenRect.width / transformInfo.viewBox[2];
        adjustedPx = textStyle.fontSize * screenPxPerViewBoxUnit;
      }
    }

    return `${fontStyle}${fontWeight}${adjustedPx}px ${fontFamily}`;
  }

  /**
   * Clear text measurement cache
   */
  static clearTextMeasureCache() {
    if (_textMeasureCache) {
      _textMeasureCache.clear();
    }
  }

  /**
   * Get text measurement cache statistics
   */
  static getTextMeasureCacheStats() {
    return {
      size: _textMeasureCache?.size || 0,
      keys: _textMeasureCache ? Array.from(_textMeasureCache.keys()) : []
    };
  }

  /**
   * Parse gradient configuration from various formats
   * @param {string|object} gradientConfig - Gradient configuration
   * @returns {object|null} Parsed gradient configuration
   */
  static parseGradientConfig(gradientConfig) {
    if (!gradientConfig) return null;

    if (typeof gradientConfig === 'string') {
      // Handle simple formats: "red,blue" or "red-to-blue"
      if (gradientConfig.includes(',')) {
        const colors = gradientConfig.split(',').map(c => c.trim());
        return {
          type: 'linear',
          direction: 'horizontal',
          stops: colors.map((color, index) => ({
            offset: `${(index / (colors.length - 1)) * 100}%`,
            color: color
          }))
        };
      } else if (gradientConfig.includes('-to-')) {
        const [color1, color2] = gradientConfig.split('-to-').map(c => c.trim());
        return {
          type: 'linear',
          direction: 'horizontal',
          stops: [
            { offset: '0%', color: color1 },
            { offset: '100%', color: color2 }
          ]
        };
      }
      return null;
    }

    if (typeof gradientConfig === 'object') {
      return {
        type: gradientConfig.type || 'linear',
        direction: gradientConfig.direction || 'horizontal',
        x1: gradientConfig.x1 || '0%',
        y1: gradientConfig.y1 || '0%',
        x2: gradientConfig.x2 || '100%',
        y2: gradientConfig.y2 || '0%',
        cx: gradientConfig.cx || '50%',
        cy: gradientConfig.cy || '50%',
        r: gradientConfig.r || '50%',
        stops: gradientConfig.stops || [
          { offset: '0%', color: gradientConfig.from || 'var(--lcars-orange, var(--lcards-orange-medium, #ff7700))' },
          { offset: '100%', color: gradientConfig.to || 'var(--lcars-red, var(--lcards-orange-dark, #dd4444))' }
        ]
      };
    }

    return null;
  }

  /**
   * Parse pattern configuration from various formats
   * @param {string|object} patternConfig - Pattern configuration
   * @returns {object|null} Parsed pattern configuration
   */
  static parsePatternConfig(patternConfig) {
    if (!patternConfig) return null;

    if (typeof patternConfig === 'string') {
      // Predefined patterns
      const presets = {
        dots: { type: 'dots', size: 8, color: 'currentColor', opacity: 0.5 },
        lines: { type: 'lines', size: 4, color: 'currentColor', opacity: 0.5 },
        diagonal: { type: 'diagonal', size: 8, color: 'currentColor', opacity: 0.5 },
        grid: { type: 'grid', size: 10, color: 'currentColor', opacity: 0.3 }
      };
      return presets[patternConfig] || null;
    }

    if (typeof patternConfig === 'object') {
      return {
        type: patternConfig.type || 'dots',
        size: Number(patternConfig.size || 8),
        color: patternConfig.color || 'currentColor',
        opacity: Number(patternConfig.opacity || 0.5),
        content: patternConfig.content || null
      };
    }

    return null;
  }

  // ========================
  // UNIFIED STYLING SYSTEM
  // ========================

  /**
   * Parse standardized text styling properties
   * Supports both flat properties and nested text object (cb-lcars legacy template format)
   *
   * @param {Object} style - Style configuration object
   * @returns {Object} Normalized text style configuration
   *
   * @example
   * // Flat format (legacy)
   * parseStandardTextStyles({ font_size: 18, label_color: 'red' })
   * // => { fontSize: 18, labelColor: 'red', ... }
   *
   * // Nested format (cb-lcars legacy templates)
   * parseStandardTextStyles({
   *   text: {
   *     label: { font_size: 20, color: 'red' },
   *     value: { font_size: 16, color: 'blue' }
   *   }
   * })
   * // => { label: { fontSize: 20, color: 'red' }, value: { fontSize: 16, color: 'blue' }, ... }
   */
  static parseStandardTextStyles(style) {
    // Helper to parse individual text element (label, value, name, state)
    const parseTextElement = (textConfig) => {
      if (!textConfig) return null;

      // Handle color state objects
      const getColorValue = (colorProp) => {
        if (!colorProp) return null;
        if (typeof colorProp === 'string') return colorProp;
        if (typeof colorProp === 'object') return colorProp.default || null;
        return null;
      };

      return {
        fontSize: textConfig.font_size !== undefined ? Number(textConfig.font_size) : null,
        fontFamily: textConfig.font_family || null,
        fontWeight: textConfig.font_weight || null,
        fontStyle: textConfig.font_style || null,
        color: getColorValue(textConfig.color),
        colorStates: typeof textConfig.color === 'object' ? textConfig.color : null,
        textAlign: textConfig.text_align || textConfig.align || null,
        textTransform: textConfig.text_transform || textConfig.transform || null,
        lineHeight: textConfig.line_height !== undefined ? Number(textConfig.line_height) : null,
        letterSpacing: textConfig.letter_spacing !== undefined ? Number(textConfig.letter_spacing) : null,
        padding: textConfig.padding ? this.parsePaddingConfig(textConfig.padding) : null
      };
    };

    // Check if using nested text structure
    const nestedText = style.text || {};
    const hasNestedText = nestedText.label || nestedText.value || nestedText.name || nestedText.state;

    const result = {
      // Core text properties (flat format - backward compatibility)
      fontSize: Number(style.font_size || style.fontSize || 12),
      fontFamily: style.font_family || style.fontFamily || 'Antonio',
      fontWeight: style.font_weight || style.fontWeight || 'normal',
      fontStyle: style.font_style || style.fontStyle || 'normal',

      // Text colors (flat format - backward compatibility)
      textColor: style.text_color || style.textColor || style.color || 'var(--lcars-text-light, var(--lcards-moonlight, #ffffff))',
      labelColor: style.label_color || style.labelColor || style.text_color || style.textColor || 'var(--lcars-text-light, var(--lcards-moonlight, #ffffff))',
      valueColor: style.value_color || style.valueColor || style.text_color || style.textColor || 'var(--lcars-text-light, var(--lcards-moonlight, #ffffff))',

      // Text alignment and positioning
      textAlign: style.text_align || style.textAlign || 'left',
      verticalAlign: style.vertical_align || style.verticalAlign || 'middle',
      textTransform: style.text_transform || style.textTransform || 'none',

      // Text effects
      textShadow: this.parseTextShadowConfig(style.text_shadow || style.textShadow),
      textStroke: this.parseTextStrokeConfig(style.text_stroke || style.textStroke),

      // Line height and spacing
      lineHeight: Number(style.line_height || style.lineHeight || 1.2),
      letterSpacing: style.letter_spacing || style.letterSpacing || 'normal'
    };

    // Add nested text elements if present (cb-lcars legacy template format)
    if (hasNestedText) {
      result.label = parseTextElement(nestedText.label);
      result.value = parseTextElement(nestedText.value);
      result.name = parseTextElement(nestedText.name);
      result.state = parseTextElement(nestedText.state);

      // Support text arrays (multiple text elements)
      if (nestedText.texts && Array.isArray(nestedText.texts)) {
        result.texts = nestedText.texts.map(textConfig => parseTextElement(textConfig));
      }
    }

    return result;
  }

  /**
   * Parse standardized color properties
   * Supports both simple string colors and color state objects
   *
   * @param {Object} style - Style configuration object
   * @returns {Object} Normalized color configuration
   *
   * @example
   * // Simple string color
   * parseStandardColorStyles({ color: 'red' })
   * // => { primaryColor: 'red', ... }
   *
   * // Color state object (cb-lcars legacy template format)
   * parseStandardColorStyles({ color: { default: 'blue', active: 'yellow' } })
   * // => { primaryColor: 'blue', primaryColorActive: 'yellow', ... }
   */
  static parseStandardColorStyles(style) {
    // Helper to extract color value (string or object.default)
    const getColorValue = (colorProp) => {
      if (!colorProp) return null;
      if (typeof colorProp === 'string') return colorProp;
      if (typeof colorProp === 'object') return colorProp.default || null;
      return null;
    };

    // Helper to extract color state object
    const getColorStates = (colorProp) => {
      if (typeof colorProp === 'object' && colorProp !== null) {
        return {
          default: colorProp.default || null,
          active: colorProp.active || null,
          inactive: colorProp.inactive || null,
          unavailable: colorProp.unavailable || null,
          zero: colorProp.zero || null,
          non_zero: colorProp.non_zero || null,
          hvac_heat: colorProp.hvac_heat || null,
          hvac_cool: colorProp.hvac_cool || null
        };
      }
      return null;
    };

    const primaryColorValue = getColorValue(style.color) ||
                             getColorValue(style.primary_color) ||
                             getColorValue(style.primaryColor) ||
                             'var(--lcars-blue, var(--lcards-blue-medium, #4455ff))';

    const backgroundColorValue = getColorValue(style.background_color) ||
                                 getColorValue(style.backgroundColor) ||
                                 'transparent';

    const borderColorValue = getColorValue(style.border_color) ||
                            getColorValue(style.borderColor) ||
                            'var(--lcars-gray, var(--lcards-gray-medium, #666688))';

    return {
      // Primary colors (string values)
      primaryColor: primaryColorValue,
      backgroundColor: backgroundColorValue,
      borderColor: borderColorValue,

      // Color states (if color is an object with states)
      primaryColorStates: getColorStates(style.color),
      backgroundColorStates: getColorStates(style.background_color || style.backgroundColor),

      // Interactive states
      hoverColor: style.hover_color || style.hoverColor || 'var(--lcars-yellow, var(--lcards-yellow-medium, #ffcc33))',
      activeColor: style.active_color || style.activeColor || 'var(--lcars-cyan, var(--lcards-blue-light, #88ccff))',
      focusColor: style.focus_color || style.focusColor || 'var(--lcars-text-light, var(--lcards-moonlight, #ffffff))',
      disabledColor: style.disabled_color || style.disabledColor || 'var(--lcars-gray, var(--lcards-gray-medium, #666688))',

      // Status colors
      successColor: style.success_color || style.successColor || 'var(--lcars-green, var(--lcards-green-medium, #33cc99))',
      warningColor: style.warning_color || style.warningColor || 'var(--lcars-yellow, var(--lcards-yellow-medium, #ffcc33))',
      errorColor: style.error_color || style.errorColor || 'var(--lcars-red, var(--lcards-orange-dark, #dd4444))',
      infoColor: style.info_color || style.infoColor || 'var(--lcars-cyan, var(--lcards-blue-light, #88ccff))'
    };
  }

  /**
   * Parse standardized layout and spacing properties
   * @param {Object} style - Style configuration object
   * @returns {Object} Normalized layout configuration
   */
  static parseStandardLayoutStyles(style) {
    return {
      // NOTE: Border properties now handled by parseStandardBorderStyles()

      // Spacing (supports both number and object formats)
      padding: this.parsePaddingConfig(style.padding),
      margin: this.parseMarginConfig(style.margin),

      // Opacity and visibility
      opacity: Number(style.opacity || 1),
      visible: style.visible !== false,

      // Size constraints
      minWidth: style.min_width || style.minWidth || null,
      maxWidth: style.max_width || style.maxWidth || null,
      minHeight: style.min_height || style.minHeight || null,
      maxHeight: style.max_height || style.maxHeight || null
    };
  }

  /**
   * Parse standardized interaction properties
   * @param {Object} style - Style configuration object
   * @returns {Object} Normalized interaction configuration
   */
  static parseStandardInteractionStyles(style) {
    return {
      // Hover effects
      hoverEnabled: style.hover_enabled !== false,
      hoverScale: Number(style.hover_scale || style.hoverScale || 1.05),
      hoverOpacity: Number(style.hover_opacity || style.hoverOpacity || 1),
      hoverTransition: style.hover_transition || style.hoverTransition || 'all 0.2s ease',

      // Click/touch effects
      clickable: style.clickable !== false,
      activeScale: Number(style.active_scale || style.activeScale || 0.95),

      // Focus styles
      focusEnabled: style.focus_enabled !== false,
      focusOutline: style.focus_outline || style.focusOutline || true,

      // Cursor
      cursor: style.cursor || 'default'
    };
  }

  /**
   * Parse standardized animation properties
   * @param {Object} style - Style configuration object
   * @returns {Object} Normalized animation configuration
   */
  static parseStandardAnimationStyles(style) {
    return {
      // Animation enablement
      animatable: style.animatable !== false,

      // Transition properties
      transition: style.transition || 'all 0.3s ease',
      transitionDelay: style.transition_delay || style.transitionDelay || '0s',
      transitionDuration: style.transition_duration || style.transitionDuration || '0.3s',
      transitionTimingFunction: style.transition_timing_function || style.transitionTimingFunction || 'ease',

      // Animation properties
      animationDuration: style.animation_duration || style.animationDuration || '1s',
      animationTimingFunction: style.animation_timing_function || style.animationTimingFunction || 'ease',
      animationDelay: style.animation_delay || style.animationDelay || '0s',
      animationIterationCount: style.animation_iteration_count || style.animationIterationCount || '1',
      animationDirection: style.animation_direction || style.animationDirection || 'normal',
      animationFillMode: style.animation_fill_mode || style.animationFillMode || 'both',

      // Custom animation properties
      cascadeSpeed: Number(style.cascade_speed || style.cascadeSpeed || 0),
      cascadeDirection: style.cascade_direction || style.cascadeDirection || 'row',
      revealAnimation: style.reveal_animation || style.revealAnimation || false,
      pulseOnChange: style.pulse_on_change || style.pulseOnChange || false
    };
  }

  /**
   * Parse standardized border properties
   * Accepts both legacy flat format and new nested format
   * Always returns normalized nested structure with camelCase
   *
   * @param {Object} style - Style configuration object
   * @returns {Object} Normalized border configuration with nested structure
   *
   * @example
   * // Legacy flat format (still supported)
   * parseStandardBorderStyles({ border_color: 'red', border_width: 2 })
   * // => { color: 'red', width: 2, radius: 0, ... }
   *
   * // New nested format (preferred)
   * parseStandardBorderStyles({ border: { color: 'red', width: 2 } })
   * // => { color: 'red', width: 2, radius: 0, ... }
   *
   * // With individual sides
   * parseStandardBorderStyles({ border: { width: 2, top: { width: 4 } } })
   * // => { width: 2, top: { width: 4 }, ... }
   */
  static parseStandardBorderStyles(style) {
    // Handle legacy flat format (border_color, border_width, etc.)
    const legacyBorder = {
      color: style.border_color || style.borderColor,
      width: style.border_width || style.borderWidth,
      radius: style.border_radius || style.borderRadius,
      style: style.border_style || style.borderStyle
    };

    // Handle new nested format
    const nestedBorder = style.border || {};

    // Parse individual side (used for all sides: top, right, bottom, left)
    const parseBorderSide = (nested, legacy) => {
      if (!nested && !legacy) return null;

      const side = nested || legacy || {};
      return {
        color: side.color || null,
        width: side.width !== undefined ? Number(side.width) : null,
        style: side.style || null
      };
    };

    // Merge (nested takes precedence over legacy)
    const border = {
      // Default properties (apply to all sides unless overridden)
      color: nestedBorder.color || legacyBorder.color || 'var(--lcars-gray, var(--lcards-gray-medium, #666688))',
      width: nestedBorder.width !== undefined ? Number(nestedBorder.width) :
             legacyBorder.width !== undefined ? Number(legacyBorder.width) : 1,
      radius: nestedBorder.radius !== undefined ? Number(nestedBorder.radius) :
              legacyBorder.radius !== undefined ? Number(legacyBorder.radius) : 0,
      style: nestedBorder.style || legacyBorder.style || 'solid',

      // Individual sides (can override defaults)
      // Support both nested format (border.top) and legacy format (border_top)
      top: parseBorderSide(nestedBorder.top, style.border_top),
      right: parseBorderSide(nestedBorder.right, style.border_right),
      bottom: parseBorderSide(nestedBorder.bottom, style.border_bottom),
      left: parseBorderSide(nestedBorder.left, style.border_left),

      // Individual corners (convert snake_case to camelCase for internal use)
      // Support both nested (border.radius_top_left) and legacy (border_radius_top_left)
      radiusTopLeft: nestedBorder.radius_top_left !== undefined ? Number(nestedBorder.radius_top_left) :
                     style.border_radius_top_left !== undefined ? Number(style.border_radius_top_left) :
                     // Legacy cb-lcars template format: border.top.left_radius
                     nestedBorder.top?.left_radius !== undefined ? Number(nestedBorder.top.left_radius) :
                     style.border_top?.left_radius !== undefined ? Number(style.border_top.left_radius) : null,

      radiusTopRight: nestedBorder.radius_top_right !== undefined ? Number(nestedBorder.radius_top_right) :
                      style.border_radius_top_right !== undefined ? Number(style.border_radius_top_right) :
                      // Legacy cb-lcars template format: border.top.right_radius
                      nestedBorder.top?.right_radius !== undefined ? Number(nestedBorder.top.right_radius) :
                      style.border_top?.right_radius !== undefined ? Number(style.border_top.right_radius) : null,

      radiusBottomRight: nestedBorder.radius_bottom_right !== undefined ? Number(nestedBorder.radius_bottom_right) :
                         style.border_radius_bottom_right !== undefined ? Number(style.border_radius_bottom_right) :
                         // Legacy cb-lcars template format: border.bottom.right_radius
                         nestedBorder.bottom?.right_radius !== undefined ? Number(nestedBorder.bottom.right_radius) :
                         style.border_bottom?.right_radius !== undefined ? Number(style.border_bottom.right_radius) : null,

      radiusBottomLeft: nestedBorder.radius_bottom_left !== undefined ? Number(nestedBorder.radius_bottom_left) :
                        style.border_radius_bottom_left !== undefined ? Number(style.border_radius_bottom_left) :
                        // Legacy cb-lcars template format: border.bottom.left_radius
                        nestedBorder.bottom?.left_radius !== undefined ? Number(nestedBorder.bottom.left_radius) :
                        style.border_bottom?.left_radius !== undefined ? Number(style.border_bottom.left_radius) : null
    };

    return border;
  }

  // ========================
  // HELPER PARSING METHODS
  // ========================

  /**
   * Parse text shadow configuration
   * @param {Object} shadowConfig - Text shadow configuration
   * @returns {Object|null} Normalized text shadow configuration
   */
  static parseTextShadowConfig(shadowConfig) {
    if (!shadowConfig) return null;

    return {
      offsetX: Number(shadowConfig.offset_x || shadowConfig.offsetX || 1),
      offsetY: Number(shadowConfig.offset_y || shadowConfig.offsetY || 1),
      blur: Number(shadowConfig.blur || 2),
      color: shadowConfig.color || 'rgba(0,0,0,0.5)'
    };
  }

  /**
   * Parse text stroke configuration
   * @param {Object} strokeConfig - Text stroke configuration
   * @returns {Object|null} Normalized text stroke configuration
   */
  static parseTextStrokeConfig(strokeConfig) {
    if (!strokeConfig) return null;

    return {
      width: Number(strokeConfig.width || 1),
      color: strokeConfig.color || 'var(--lcars-gray, var(--lcards-gray-medium, #666688))',
      opacity: Number(strokeConfig.opacity || 1)
    };
  }

  /**
   * Parse padding configuration (supports number or object)
   * @param {number|Object} padding - Padding configuration
   * @returns {Object} Normalized padding configuration
   */
  static parsePaddingConfig(padding) {
    if (typeof padding === 'number') {
      return { top: padding, right: padding, bottom: padding, left: padding };
    }

    if (typeof padding === 'object' && padding !== null) {
      return {
        top: Number(padding.top || padding.vertical || 0),
        right: Number(padding.right || padding.horizontal || 0),
        bottom: Number(padding.bottom || padding.vertical || 0),
        left: Number(padding.left || padding.horizontal || 0)
      };
    }

    return { top: 0, right: 0, bottom: 0, left: 0 };
  }

  /**
   * Parse margin configuration (supports number or object)
   * @param {number|Object} margin - Margin configuration
   * @returns {Object} Normalized margin configuration
   */
  static parseMarginConfig(margin) {
    if (typeof margin === 'number') {
      return { top: margin, right: margin, bottom: margin, left: margin };
    }

    if (typeof margin === 'object' && margin !== null) {
      return {
        top: Number(margin.top || margin.vertical || 0),
        right: Number(margin.right || margin.horizontal || 0),
        bottom: Number(margin.bottom || margin.vertical || 0),
        left: Number(margin.left || margin.horizontal || 0)
      };
    }

    return { top: 0, right: 0, bottom: 0, left: 0 };
  }

  // ========================
  // STYLE APPLICATION HELPERS
  // ========================

  /**
   * Apply standard text styles to an SVG text element
   * @param {Object} textStyles - Parsed text styles
   * @returns {string} SVG text attributes string
   */
  static applyStandardTextStyles(textStyles) {
    const attributes = [];

    attributes.push(`font-family="${textStyles.fontFamily}"`);
    attributes.push(`font-size="${textStyles.fontSize}"`);
    attributes.push(`font-weight="${textStyles.fontWeight}"`);
    attributes.push(`font-style="${textStyles.fontStyle}"`);
    attributes.push(`fill="${textStyles.textColor}"`);
    attributes.push(`text-anchor="${textStyles.textAlign}"`);
    attributes.push(`dominant-baseline="${textStyles.verticalAlign}"`);
    attributes.push(`letter-spacing="${textStyles.letterSpacing}"`);

    if (textStyles.textStroke) {
      attributes.push(`stroke="${textStyles.textStroke.color}"`);
      attributes.push(`stroke-width="${textStyles.textStroke.width}"`);
      attributes.push(`stroke-opacity="${textStyles.textStroke.opacity}"`);
    }

    return attributes.join(' ');
  }

  /**
   * Apply standard layout styles to an SVG element
   * @param {Object} layoutStyles - Parsed layout styles
   * @returns {string} SVG element attributes string
   */
  static applyStandardLayoutStyles(layoutStyles) {
    const attributes = [];

    if (layoutStyles.borderWidth > 0) {
      attributes.push(`stroke-width="${layoutStyles.borderWidth}"`);
    }

    if (layoutStyles.borderRadius > 0) {
      attributes.push(`rx="${layoutStyles.borderRadius}"`);
      attributes.push(`ry="${layoutStyles.borderRadius}"`);
    }

    attributes.push(`opacity="${layoutStyles.opacity}"`);

    if (!layoutStyles.visible) {
      attributes.push(`style="display: none"`);
    }

    return attributes.join(' ');
  }

  /**
   * Create CSS text-shadow value from parsed config
   * @param {Object} textShadow - Parsed text shadow configuration
   * @returns {string} CSS text-shadow value
   */
  static createTextShadowCSS(textShadow) {
    if (!textShadow) return '';
    return `${textShadow.offsetX}px ${textShadow.offsetY}px ${textShadow.blur}px ${textShadow.color}`;
  }

  /**
   * Generate data attributes for animation integration
   * @param {Object} animationStyles - Parsed animation styles
   * @returns {string} Data attributes string
   */
  static createAnimationDataAttributes(animationStyles) {
    const attributes = [];

    if (animationStyles.animatable) {
      attributes.push(`data-animatable="true"`);
    }

    if (animationStyles.cascadeSpeed > 0) {
      attributes.push(`data-cascade-speed="${animationStyles.cascadeSpeed}"`);
      attributes.push(`data-cascade-direction="${animationStyles.cascadeDirection}"`);
    }

    if (animationStyles.revealAnimation) {
      attributes.push(`data-reveal-animation="true"`);
    }

    if (animationStyles.pulseOnChange) {
      attributes.push(`data-pulse-on-change="true"`);
    }

    return attributes.join(' ');
  }

  /**
   * Create gradient definition SVG
   * @param {object} gradient - Parsed gradient configuration
   * @param {string} id - Unique ID for the gradient
   * @returns {string} SVG gradient definition
   */
  static createGradientDefinition(gradient, id) {
    if (gradient.type === 'radial') {
      const stops = gradient.stops.map(stop =>
        `<stop offset="${stop.offset}" stop-color="${stop.color}"/>`
      ).join('');

      return `<radialGradient id="${id}" cx="${gradient.cx}" cy="${gradient.cy}" r="${gradient.r}">
                ${stops}
              </radialGradient>`;
    } else {
      // Linear gradient
      const coords = this.getLinearGradientCoords(gradient.direction, gradient);
      const stops = gradient.stops.map(stop =>
        `<stop offset="${stop.offset}" stop-color="${stop.color}"/>`
      ).join('');

      return `<linearGradient id="${id}" ${coords}>
                ${stops}
              </linearGradient>`;
    }
  }

  /**
   * Get linear gradient coordinates based on direction
   * @param {string} direction - Gradient direction
   * @param {object} gradient - Gradient configuration (for custom coordinates)
   * @returns {string} SVG coordinate attributes
   */
  static getLinearGradientCoords(direction, gradient = {}) {
    // Use custom coordinates if provided
    if (gradient.x1 !== undefined) {
      return `x1="${gradient.x1}" y1="${gradient.y1}" x2="${gradient.x2}" y2="${gradient.y2}"`;
    }

    // Predefined directions
    const directions = {
      horizontal: 'x1="0%" y1="0%" x2="100%" y2="0%"',
      vertical: 'x1="0%" y1="0%" x2="0%" y2="100%"',
      diagonal: 'x1="0%" y1="0%" x2="100%" y2="100%"',
      'diagonal-reverse': 'x1="100%" y1="0%" x2="0%" y2="100%"',
      'to-right': 'x1="0%" y1="0%" x2="100%" y2="0%"',
      'to-left': 'x1="100%" y1="0%" x2="0%" y2="0%"',
      'to-bottom': 'x1="0%" y1="0%" x2="0%" y2="100%"',
      'to-top': 'x1="0%" y1="100%" x2="0%" y2="0%"'
    };

    return directions[direction] || directions.horizontal;
  }

  /**
   * Create pattern definition SVG
   * @param {object} pattern - Parsed pattern configuration
   * @param {string} id - Unique ID for the pattern
   * @returns {string} SVG pattern definition
   */
  static createPatternDefinition(pattern, id) {
    const size = pattern.size;
    const color = pattern.color;
    const opacity = pattern.opacity;

    let patternContent = '';

    switch (pattern.type) {
      case 'dots':
        patternContent = `<circle cx="${size/2}" cy="${size/2}" r="1"
                                  fill="${color}" opacity="${opacity}"/>`;
        break;

      case 'lines':
        patternContent = `<path d="M 0,${size} l ${size},-${size} M -1,1 l 2,-2 M ${size-1},${size+1} l 2,-2"
                                stroke="${color}" stroke-width="1" opacity="${opacity}"/>`;
        break;

      case 'diagonal':
        patternContent = `<path d="M0,${size} L${size},0"
                                stroke="${color}" stroke-width="1" opacity="${opacity}"/>`;
        break;

      case 'grid':
        patternContent = `
          <path d="M0,0 L0,${size}" stroke="${color}" stroke-width="0.5" opacity="${opacity}"/>
          <path d="M0,0 L${size},0" stroke="${color}" stroke-width="0.5" opacity="${opacity}"/>
        `;
        break;

      case 'custom':
        patternContent = pattern.content || '';
        break;

      default:
        // Default to dots
        patternContent = `<circle cx="${size/2}" cy="${size/2}" r="1"
                                  fill="${color}" opacity="${opacity}"/>`;
    }

    return `<pattern id="${id}" x="0" y="0" width="${size}" height="${size}"
                     patternUnits="userSpaceOnUse">
              ${patternContent}
            </pattern>`;
  }

  /**
   * Create LCARS-style bracket path
   * @param {number} width - Bracket width
   * @param {number} height - Bracket height
   * @param {string} side - 'left' or 'right'
   * @param {object} options - Styling options
   * @returns {string} SVG path for bracket
   */
  static createLcarsBracket(width, height, side = 'left', options = {}) {
    const bracketWidth = options.bracketWidth || 8;
    const cornerRadius = options.cornerRadius || 2;
    const strokeWidth = options.strokeWidth || 2;
    const color = options.color || 'var(--lcars-orange, var(--lcards-orange-medium, #ff7700))';

    let pathData = '';

    if (side === 'left') {
      pathData = `M ${width} 0 L ${cornerRadius} 0
                  Q 0 0 0 ${cornerRadius}
                  L 0 ${height - cornerRadius}
                  Q 0 ${height} ${cornerRadius} ${height}
                  L ${width} ${height}`;
    } else {
      pathData = `M 0 0 L ${width - cornerRadius} 0
                  Q ${width} 0 ${width} ${cornerRadius}
                  L ${width} ${height - cornerRadius}
                  Q ${width} ${height} ${width - cornerRadius} ${height}
                  L 0 ${height}`;
    }

    return `<path d="${pathData}"
                  stroke="${color}"
                  stroke-width="${strokeWidth}"
                  fill="none"/>`;
  }

  /**
   * Create marker definition for arrows, dots, etc.
   * @param {object} marker - Marker configuration
   * @param {string} id - Unique ID for the marker
   * @returns {string} SVG marker definition
   */
  static createMarkerDefinition(marker, id) {
    const size = this.getMarkerSize(marker.size || 'medium');
    const color = marker.color === 'inherit' ? 'currentColor' : marker.color;

    let markerContent = '';
    let viewBox = `0 0 ${size} ${size}`;
    let refX = size / 2;
    let refY = size / 2;

    switch (marker.type) {
      case 'arrow':
        viewBox = '0 0 10 10';
        refX = 8;
        refY = 5;
        markerContent = `<path d="M2,2 L8,5 L2,8 z" fill="${color}"/>`;
        break;

      case 'dot':
      case 'circle':
        markerContent = `<circle cx="${size/2}" cy="${size/2}" r="${size/4}" fill="${color}"/>`;
        break;

      case 'diamond':
        markerContent = `<path d="M${size/2},2 L${size-2},${size/2} L${size/2},${size-2} L2,${size/2} z" fill="${color}"/>`;
        break;

      case 'square':
        markerContent = `<rect x="2" y="2" width="${size-4}" height="${size-4}" fill="${color}"/>`;
        break;

      case 'triangle':
        markerContent = `<path d="M${size/2},2 L${size-2},${size-2} L2,${size-2} z" fill="${color}"/>`;
        break;

      default:
        markerContent = `<circle cx="${size/2}" cy="${size/2}" r="${size/4}" fill="${color}"/>`;
    }

    return `<marker id="${id}"
                    viewBox="${viewBox}"
                    refX="${refX}" refY="${refY}"
                    markerWidth="${size}" markerHeight="${size}"
                    markerUnits="strokeWidth"
                    orient="${marker.rotate !== false ? 'auto' : '0'}">
              ${markerContent}
            </marker>`;
  }

  /**
   * Get numeric marker size from size descriptor
   * @param {string|number} size - Size descriptor
   * @returns {number} Numeric size
   */
  static getMarkerSize(size) {
    if (typeof size === 'number') return size;

    const sizes = {
      small: 6,
      medium: 8,
      large: 12,
      xlarge: 16
    };

    return sizes[size] || 8;
  }

  /**
   * Escape XML special characters
   * @param {string} text - Text to escape
   * @returns {string} Escaped text
   */
  static escapeXml(text) {
    return String(text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  /**
   * Generate unique ID for elements
   * @param {string} prefix - Prefix for the ID
   * @param {string} suffix - Suffix for the ID
   * @returns {string} Unique ID
   */
  static generateId(prefix = 'element', suffix = '') {
    const timestamp = Date.now().toString(36);
    const random = Math.random().toString(36).substr(2, 5);
    return `${prefix}-${timestamp}-${random}${suffix ? '-' + suffix : ''}`;
  }

  /**
   * Parse CSS color values and convert to various formats
   * @param {string} color - CSS color value
   * @returns {object} Color information
   */
  static parseColor(color) {
    // Create a temporary element to leverage browser's color parsing
    const tempElement = document.createElement('div');
    tempElement.style.color = color;
    document.body.appendChild(tempElement);

    const computedColor = getComputedStyle(tempElement).color;
    document.body.removeChild(tempElement);

    // Parse RGB values
    const rgbMatch = computedColor.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
    if (rgbMatch) {
      const r = parseInt(rgbMatch[1]);
      const g = parseInt(rgbMatch[2]);
      const b = parseInt(rgbMatch[3]);

      return {
        rgb: [r, g, b],
        hex: this.rgbToHex(r, g, b),
        hsl: this.rgbToHsl(r, g, b),
        original: color,
        computed: computedColor
      };
    }

    return {
      original: color,
      computed: computedColor
    };
  }

  /**
   * Convert RGB to HEX
   * @private
   */
  static rgbToHex(r, g, b) {
    return ColorUtils.rgbToHex(r, g, b);
  }

  /**
   * Convert RGB to HSL
   * @private
   */
  static rgbToHsl(r, g, b) {
    const [h, s, l] = ColorUtils.rgbToHsl(r, g, b);
    return [Math.round(h), Math.round(s), Math.round(l)];
  }

  /**
   * Calculate optimal text contrast color
   * @param {string} backgroundColor - Background color
   * @returns {string} Optimal text color (black or white)
   */
  static getContrastColor(backgroundColor) {
    const color = this.parseColor(backgroundColor);
    if (!color.rgb) return '#ffffff';

    const [r, g, b] = color.rgb;
    const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;

    return luminance > 0.5 ? '#000000' : '#ffffff';
  }

  /**
   * Interpolate between two colors
   * @param {string} color1 - Start color
   * @param {string} color2 - End color
   * @param {number} factor - Interpolation factor (0-1)
   * @returns {string} Interpolated color
   */
  static interpolateColor(color1, color2, factor) {
    const c1 = this.parseColor(color1);
    const c2 = this.parseColor(color2);

    if (!c1.rgb || !c2.rgb) return color1;

    const r = Math.round(c1.rgb[0] + (c2.rgb[0] - c1.rgb[0]) * factor);
    const g = Math.round(c1.rgb[1] + (c2.rgb[1] - c1.rgb[1]) * factor);
    const b = Math.round(c1.rgb[2] + (c2.rgb[2] - c1.rgb[2]) * factor);

    return `rgb(${r}, ${g}, ${b})`;
  }

  /**
   * Create animation-ready attributes for future anime.js integration
   * @param {object} animationConfig - Animation configuration
   * @returns {array} Array of attribute strings
   */
  static createAnimationAttributes(animationConfig = {}) {
    const attributes = [];

    if (animationConfig.animatable !== false) {
      attributes.push('data-animatable="true"');
    }

    Object.keys(animationConfig).forEach(key => {
      if (key.endsWith('_speed') || key.endsWith('Speed')) {
        const value = animationConfig[key];
        if (value > 0) {
          const dataKey = key.replace(/([A-Z])/g, '-$1').toLowerCase().replace('_', '-');
          attributes.push(`data-${dataKey}="${value}"`);
        }
      }
    });

    // animation_ref removed - animations now defined directly on overlays

    return attributes;
  }

  /**
   * Validate and sanitize style values
   * @param {object} styles - Style object to validate
   * @returns {object} Sanitized styles
   */
  static sanitizeStyles(styles) {
    const sanitized = {};

    // Define allowed properties and their validation functions
    const validators = {
      color: (value) => this.isValidColor(value),
      opacity: (value) => this.isValidOpacity(value),
      width: (value) => this.isValidNumber(value),
      height: (value) => this.isValidNumber(value),
      stroke: (value) => this.isValidColor(value),
      fill: (value) => this.isValidColor(value) || value === 'none',
      fontSize: (value) => this.isValidNumber(value),
      fontFamily: (value) => this.isValidString(value)
    };

    Object.keys(styles).forEach(key => {
      const validator = validators[key] || validators[this.camelToKebab(key)];
      if (validator && validator(styles[key])) {
        sanitized[key] = styles[key];
      }
    });

    return sanitized;
  }

  /**
   * Check if value is a valid color
   * @private
   */
  static isValidColor(value) {
    if (typeof value !== 'string') return false;
    return /^(#[0-9a-f]{3,8}|rgb\(|rgba\(|hsl\(|hsla\(|var\(--|\w+)/.test(value.toLowerCase());
  }

  /**
   * Check if value is a valid opacity
   * @private
   */
  static isValidOpacity(value) {
    const num = Number(value);
    return !isNaN(num) && num >= 0 && num <= 1;
  }

  /**
   * Check if value is a valid number
   * @private
   */
  static isValidNumber(value) {
    return !isNaN(Number(value)) && isFinite(Number(value));
  }

  /**
   * Check if value is a valid string
   * @private
   */
  static isValidString(value) {
    return typeof value === 'string' && value.length > 0;
  }

  /**
   * Convert camelCase to kebab-case
   * @private
   */
  static camelToKebab(str) {
    return str.replace(/([A-Z])/g, '-$1').toLowerCase();
  }

  /**
   * Get DOM text bounding box for glyphs (after font load)
   * @param {Element} groupEl - SVG group element containing the text
   * @returns {Object|null} Bounding box object with width, height, and position
   */
  static getDomTextBBox(groupEl) {
    try {
      if (!groupEl) return null;
      const textEl = groupEl.querySelector('text');
      if (!textEl) return null;
      const bb = textEl.getBBox();
      return {
        width: bb.width,
        height: bb.height,
        left: bb.x,
        top: bb.y,
        right: bb.x + bb.width,
        bottom: bb.y + bb.height,
        centerX: bb.x + bb.width / 2,
        centerY: bb.y + bb.height / 2
      };
    } catch(_) {
      return null;
    }
  }
}

// Expose cache-clear for cross-module callers (e.g. LCARdSNativeCard font reload handler)
// that cannot import MSD utilities directly.
if (typeof window !== 'undefined') {
  window.lcards = window.lcards || {};
  window.lcards.clearTextMeasureCache = () => RendererUtils.clearTextMeasureCache();
}