/**
 * @fileoverview LCARdS MSD Live Preview
 *
 * Renders a live preview of the MSD card with current configuration.
 * Updates automatically when config changes (debounced 300ms).
 *
 * @element lcards-msd-live-preview
 *
 * @property {Object} hass - Home Assistant instance
 * @property {Object} config - Current MSD card configuration
 * @property {Boolean} showRefreshButton - Show manual refresh button (default: true)
 *
 * @example
 * <lcards-msd-live-preview
 *   .hass=${this.hass}
 *   .config=${this._workingConfig}
 *   .showRefreshButton=${true}>
 * </lcards-msd-live-preview>
 */

import { LitElement, html, css } from 'lit';
import { lcardsLog } from '../../utils/lcards-logging.js';
import '../../cards/lcards-msd.js';  // Import the MSD card component

export class LCARdSMSDLivePreview extends LitElement {

    static properties = {
        hass: { type: Object },
        config: { type: Object },
        showRefreshButton: { type: Boolean },
        _renderKey: { type: Number, state: true },
        _debounceTimer: { state: true }
    };

    constructor() {
        super();
        this.hass = null;
        this.config = null;
        this.showRefreshButton = true;
        this._renderKey = 0;
        this._debounceTimer = null;
    }

    static get styles() {
        return css`
            :host {
                display: block;
                height: 100%;
            }

            .preview-container {
                display: flex;
                flex-direction: column;
                height: 100%;
                background: var(--secondary-background-color, #fafafa);
                border-radius: 8px;
                overflow: hidden;
            }

            .preview-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
                padding: 0px 16px;
                background: var(--card-background-color, white);
                border-bottom: var(--ha-border-width-md) solid var(--divider-color, #e0e0e0);
                font-weight: 600;
                font-size: 14px;
            }

            .preview-title {
                display: flex;
                align-items: center;
                gap: 8px;
            }

            .preview-card-container {
                flex: 1;
                padding: 16px;
                overflow: visible;  /* Allow zoomed content to extend beyond bounds */
                position: relative;
                display: flex;
                align-items: center;
                justify-content: center;
                background: var(--primary-background-color, #fafafa);
            }

            .zoom-wrapper {
                width: 100%;
                height: 100%;
                transform-origin: 0 0;
            }

            lcards-msd-card {
                max-width: 100%;
                max-height: 100%;
                box-shadow: var(--ha-box-shadow-m);
                border-radius: 4px;
            }

            .preview-footer {
                padding: 8px 16px;
                background: var(--card-background-color, white);
                border-top: var(--ha-border-width-sm) solid var(--divider-color, #e0e0e0);
                font-size: 12px;
                color: var(--secondary-text-color, #727272);
                display: flex;
                align-items: center;
                gap: 4px;
            }

            .preview-empty {
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                padding: 48px 24px;
                color: var(--disabled-text-color, #9e9e9e);
                text-align: center;
                height: 100%;
            }

            .preview-empty ha-icon {
                --mdc-icon-size: 64px;
                margin-bottom: 16px;
            }

            .empty-message {
                font-size: 16px;
                font-weight: 500;
                margin: 0 0 8px 0;
            }

            .empty-helper {
                font-size: 14px;
                margin: 0;
            }

            .preview-error {
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                padding: 48px 24px;
                color: var(--error-color, #ff0000);
                text-align: center;
                height: 100%;
            }

            .preview-error ha-icon {
                --mdc-icon-size: 64px;
                margin-bottom: 16px;
            }

            .error-message {
                font-size: 16px;
                font-weight: 500;
                margin: 0 0 8px 0;
            }

            .error-details {
                font-size: 14px;
                margin: 0;
                font-family: monospace;
            }
        `;
    }

    /**
     * Lifecycle: First update
     * Initialize preview card
     */
    firstUpdated() {
        // @ts-ignore - TS2554: auto-suppressed
        super.firstUpdated();
        // Initial preview render
        this._updatePreviewCard();
    }

    /**
     * Lifecycle: Property changed
     * Schedule preview update on config change
     */
    updated(changedProps) {
        super.updated(changedProps);

        if (changedProps.has('config') || changedProps.has('hass')) {
            this._schedulePreviewUpdate();
        }
    }

    /**
     * Schedule debounced preview update (300ms)
     * @private
     */
    _schedulePreviewUpdate() {
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
        }

        this._debounceTimer = setTimeout(() => {
            this._renderKey++;
            this._updatePreviewCard();
            this._debounceTimer = null;
            lcardsLog.debug('[MSDLivePreview] Preview updated (debounced)');
        }, 300);
    }

    /**
     * Force immediate preview refresh
     * @private
     */
    _forceRefresh() {
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
        this._renderKey++;
        this._updatePreviewCard();
        lcardsLog.debug('[MSDLivePreview] Preview refreshed (manual)');
    }

    /**
     * Update preview card (manual DOM manipulation like chart studio)
     * @private
     */
    _updatePreviewCard() {
        const container = this.shadowRoot?.querySelector('.preview-card-container');
        if (!container) {
            lcardsLog.warn('[MSDLivePreview] Card container not found');
            return;
        }

        // Clear existing preview
        while (container.firstChild) {
            container.firstChild.remove();
        }

        // Check if we have base SVG configured
        if (!this._hasBaseSvg()) {
            // Render empty state directly in container
            container.innerHTML = `
                <div class="preview-empty">
                    <ha-icon icon="mdi:image-off"></ha-icon>
                    <p class="empty-message">No base SVG configured</p>
                    <p class="empty-helper">
                        Configure a base SVG in the "Base SVG" tab to see the preview
                    </p>
                </div>
            `;
            return;
        }

        // Get preview config
        const previewConfig = this._getPreviewConfig();
        if (!previewConfig) {
            lcardsLog.warn('[MSDLivePreview] No valid config for preview');
            return;
        }

        try {
            // Manually create card element
            const card = document.createElement('lcards-msd-card');

            lcardsLog.debug('[MSDLivePreview] Creating preview card with config:', previewConfig);
            lcardsLog.debug('[MSDLivePreview] HASS object available:', !!this.hass);

            // CRITICAL: Set config and hass BEFORE appending
            // This ensures setConfig() is called before hass is set
            // @ts-ignore - TS2339: auto-suppressed
            card.setConfig(previewConfig);
            if (this.hass) {
                // @ts-ignore - TS2339: auto-suppressed
                card.hass = this.hass;
            }

            // NOW append to DOM after card is fully configured
            container.appendChild(card);

            lcardsLog.debug('[MSDLivePreview] Preview card configured and appended');

            // card.setConfig() only *starts* the card's own async pipeline
            // init (see LCARdSCard's _processConfigAsync comment) - it
            // doesn't return anything awaitable here, so nothing tells a
            // parent (e.g. the Studio dialog) when the freshly-created
            // card's resolved model actually becomes available. Anything
            // reading `card._msdPipeline?.getResolvedModel()` synchronously
            // right after this call (or shortly after, on the *previous*
            // debounce cycle's stale card) sees a null/empty pipeline.
            // Notify once the new card's own pipeline reference lands (or
            // we give up), so listeners can re-render with fresh data
            // instead of silently going stale until something unrelated
            // happens to force another re-render.
            this._waitForPipelineReady(card).then(() => {
                this.dispatchEvent(new CustomEvent('preview-ready', { bubbles: true, composed: true }));
            });
        } catch (error) {
            lcardsLog.error('[MSDLivePreview] Failed to update preview:', error);
            this._renderErrorInContainer(container, error);
        }
    }

    /**
     * Wait for a freshly-created preview card's MSD pipeline to finish
     * initializing (its `_msdPipeline` reactive property going from null to
     * set), or give up after a timeout (e.g. pipeline init failed - the card
     * itself already handles that error case and re-renders empty/error UI,
     * we just shouldn't hang forever waiting for a value that'll never come).
     * @param {Element} card - The <lcards-msd-card> just appended
     * @param {number} [timeoutMs=5000]
     * @private
     */
    async _waitForPipelineReady(card, timeoutMs = 5000) {
        const start = Date.now();
        // @ts-ignore - TS2339: auto-suppressed
        while (!card._msdPipeline && Date.now() - start < timeoutMs) {
            // @ts-ignore - TS2339: auto-suppressed
            await card.updateComplete;
            // @ts-ignore - TS2339: auto-suppressed
            if (card._msdPipeline) break;
            await new Promise((resolve) => setTimeout(resolve, 50));
        }
    }

    /**
     * Render error state in container
     * @private
     */
    _renderErrorInContainer(container, error) {
        container.innerHTML = `
            <div class="preview-error">
                <ha-icon icon="mdi:alert-circle"></ha-icon>
                <p class="error-message">Preview Error</p>
                <p class="error-details">${error.message}</p>
            </div>
        `;
    }

    /**
     * Get a deep-cloned copy of the config for the preview card, so setting
     * it on the manually-created <lcards-msd-card> can't mutate the
     * caller's own working config.
     * @returns {Object} MSD card config
     * @private
     */
    _getPreviewConfig() {
        const previewConfig = JSON.parse(JSON.stringify(this.config || {}));

        if (!previewConfig.msd) {
            previewConfig.msd = {};
        }

        return previewConfig;
    }

    /**
     * Check if config has base SVG configured
     * @returns {boolean}
     * @private
     */
    _hasBaseSvg() {
        return !!(this.config?.msd?.base_svg);
    }

    /**
     * Render component
     */
    render() {
        return html`
            <div class="preview-container">
                <!-- Preview Card Container (populated by _updatePreviewCard) -->
                <!-- Parent .msd-zoom-wrapper provides CSS transform for zoom -->
                <div class="preview-card-container">
                </div>
            </div>
        `;
    }
}

// Register the custom element
if (!customElements.get('lcards-msd-live-preview')) customElements.define('lcards-msd-live-preview', LCARdSMSDLivePreview);
