/**
 * @fileoverview ThemeManager - Central theme system management
 *
 * Replaces DefaultsManager and ProfileResolver with unified theme-based defaults.
 * All component defaults come from active theme's component tokens.
 *
 * Features:
 * - Load themes from packs
 * - Activate/switch themes at runtime
 * - Provide component defaults via token resolution
 * - Replace DefaultsManager.getDefault() API
 * - Replace ProfileResolver style layering
 *
 * @module msd/themes/ThemeManager
 */

import { ThemeTokenResolver, initializeTokenResolver, getTokenResolver } from './ThemeTokenResolver.js';
import { lcardsLog } from '../../utils/lcards-logging.js';
import { BaseService } from '../../core/BaseService.js';
import { setAlertMode as injectAlertMode, ALERT_MODE_TRANSFORMS, captureOriginalColors } from './paletteInjector.js';
import { loadAlertTransformsFromHelpers } from './alertModeTransform.js';
import { STORAGE_KEY_THEME_OVERRIDES } from '../services/ScopedSettingsConstants.js';

/**
 * ThemeManager - Central theme system coordinator
 *
 * Manages theme loading, activation, and provides unified access to component defaults.
 * Replaces the deprecated DefaultsManager and ProfileResolver systems.
 */
export class ThemeManager extends BaseService {
  constructor() {
    super();
    /** @type {Map<string, Object>} Theme ID -> Theme object */
    this.themes = new Map();

    /** @type {string|null} Active theme ID */
    this.activeThemeId = null;

    /** @type {Object|null} Active theme object */
    this.activeTheme = null;

    /** @type {ThemeTokenResolver|null} Token resolver instance */
    this.resolver = null;

    /** @type {boolean} Initialization state */
    this.initialized = false;

    // Alert mode tracking
    this.currentAlertMode = 'green_alert';

    /**
     * Subscribers notified after an alert mode is fully applied.
     * Fires AFTER CSS variables are written, currentAlertMode is updated,
     * and the token resolver cache is cleared — safe to re-render immediately.
     * @type {Set<Function>}
     */
    this._alertModeSubscribers = new Set();

    /**
     * Subscribers notified after theme token overrides change.
     * Fires after overrides are merged and applied to the resolver.
     * @type {Set<Function>}
     */
    this._overrideSubscribers = new Set();

    /**
     * Pending setTimeout ID for the debounced `lcards:theme-overrides-changed`
     * window event.  Prevents N cards each launching a full config re-process
     * when rapid successive override writes occur (e.g. dragging a token slider).
     * @type {ReturnType<typeof setTimeout>|null}
     */
    this._overridesChangedTimer = null;

    /**
     * Serialization queue for setAlertMode(). injectAlertMode() is async (CSS
     * var writes plus a requestAnimationFrame wait, or a longer transition
     * effect), so back-to-back calls — e.g. rapid alert-mode switching —
     * could otherwise resolve out of order and let an earlier, now-stale
     * call's writes clobber a later call's result. Each call chains onto
     * this promise so calls are applied in the order they were issued.
     * @type {Promise<void>}
     */
    this._alertModeQueue = Promise.resolve();
  }

  /**
   * Register themes from a pack
   * Called by PackManager for each pack loaded
   *
   * @param {Object} pack - Pack object with themes field
   */
  registerThemesFromPack(pack) {
    if (!pack.themes || typeof pack.themes !== 'object') {
      return;
    }

    Object.entries(pack.themes).forEach(([themeId, theme]) => {
      this.themes.set(themeId, {
        ...theme,
        packId: pack.id
      });
      lcardsLog.debug(`[ThemeManager] Registered theme: ${themeId} from pack: ${pack.id}`);
    });

    this.initialized = true;
  }

  /**
   * Initialize theme system from packs
   *
   * @param {Array<Object>} packs - Loaded pack objects
   * @param {string} [requestedThemeId='lcards-default'] - Theme ID to activate
   * @param {Element} [rootElement=null] - Root element for CSS variables
   * @returns {Promise<void>}
   */
  async initialize(packs, requestedThemeId = 'lcards-default', rootElement = null) {
    lcardsLog.debug('[ThemeManager] 🎨 Initializing theme system');

    // Load all themes from packs
    this.themes.clear();
    packs.forEach(pack => {
      if (pack.themes && typeof pack.themes === 'object') {
        Object.entries(pack.themes).forEach(([themeId, theme]) => {
          this.themes.set(themeId, {
            ...theme,
            packId: pack.id
          });
          lcardsLog.debug(`[ThemeManager] Loaded theme: ${themeId} from pack: ${pack.id}`);
        });
      }
    });

    if (this.themes.size === 0) {
      lcardsLog.warn('[ThemeManager] No themes found in packs - using fallback');
    }

    // Find default theme from packs
    const packWithDefault = packs.find(pack => pack.defaultTheme);
    const fallbackThemeId = packWithDefault?.defaultTheme || 'lcards-default';

    // Activate requested theme (or fallback)
    const themeToActivate = requestedThemeId || fallbackThemeId;
    await this.activateTheme(themeToActivate, rootElement);

    this.initialized = true;

    lcardsLog.info('[ThemeManager] ✅ Theme system initialized:', {
      themeCount: this.themes.size,
      activeTheme: this.activeThemeId,
      availableThemes: Array.from(this.themes.keys())
    });
  }

  /**
   * Activate a specific theme
   *
   * @param {string} themeId - Theme ID to activate
   * @param {Element} [rootElement=null] - Root element for CSS variables
   * @returns {Promise<void>}
   * @throws {Error} If theme not found or has no tokens
   */
  async activateTheme(themeId, rootElement = null) {
    const theme = this.themes.get(themeId);

    if (!theme) {
      lcardsLog.error('[ThemeManager] Theme not found:', themeId);
      throw new Error(`Theme not found: ${themeId}`);
    }

    if (!theme.tokens) {
      lcardsLog.error('[ThemeManager] Theme has no tokens:', themeId);
      throw new Error(`Theme has no tokens: ${themeId}`);
    }

    // Initialize token resolver with theme tokens
    initializeTokenResolver(theme.tokens, rootElement);
    this.resolver = getTokenResolver();

    // Clear resolver cache on theme change
    if (this.activeThemeId && this.activeThemeId !== themeId) {
      this.resolver.clearCache();
    }

    // Load and apply scoped overrides for the new theme
    await this.loadOverrides();

    // Load theme CSS file if specified
    // (Reserved for future theme CSS override support - no themes currently ship cssFiles)
    // if (theme.cssFile) { this._loadThemeCss(theme.cssFile, themeId); }

    this.activeThemeId = themeId;
    this.activeTheme = theme;

    // Capture original --lcars-* colors for alert mode system.
    //
    // Pass 1 (synchronous): CSS vars written by initializeTokenResolver / injectPalette
    // are applied via style.setProperty and are immediately available to getComputedStyle.
    // Capturing here ensures a baseline is ALWAYS present before any setTimeout-based
    // alert mode application runs (avoids the race with HelperManager._setupAlertModeAutoSwitch).
    captureOriginalColors(rootElement);
    lcardsLog.debug('[ThemeManager] Alert mode baseline colors captured (initial pass)');

    // Pass 2 (deferred): a second capture after 150 ms lets any HA LCARS theme stylesheet
    // rules that land asynchronously (e.g. lovelace panel CSS cascade) refine the snapshot.
    //
    // GUARD: if a non-green alert mode is already active by the time this fires
    // (e.g. _tryApplyInitialAlertMode ran at ~100 ms and the lazy baseline
    // capture inside setAlertMode already populated originalLcarsColors) then
    // the --lcars-* vars are now transformed.  Re-capturing them here would
    // store the alert-shifted colours as the "original" baseline, causing
    // permanent colour drift for all subsequent mode switches.
    setTimeout(() => {
      const activeModeNow = this.currentAlertMode ?? 'green_alert';
      if (activeModeNow !== 'green_alert') {
        lcardsLog.debug(`[ThemeManager] Skipping deferred baseline recapture — non-green mode already active: ${activeModeNow}`);
        return;
      }
      captureOriginalColors(rootElement);
      lcardsLog.debug('[ThemeManager] Alert mode baseline colors re-captured (deferred pass)');
    }, 150);

    lcardsLog.info('[ThemeManager] ✅ Theme activated:', {
      id: themeId,
      name: theme.name,
      description: theme.description,
      tokenCount: this._countTokens(theme.tokens)
    });
  }

  /**
   * Get default value for a component property
   *
   * **Replaces:** DefaultsManager.getDefault()
   *
   * @param {string} componentType - Component type (e.g., 'text', 'statusGrid')
   * @param {string} property - Property name (e.g., 'defaultSize', 'defaultColor')
   * @param {*} [fallback=null] - Fallback value if token not found
   * @param {Object} [context={}] - Resolution context (viewBox, etc.)
   * @returns {*} Resolved value
   *
   * @example
   * // Get text component default font size
   * const fontSize = themeManager.getDefault('text', 'defaultSize');
   * // Returns: 14 (from theme's components.text.defaultSize token)
   *
   * @example
   * // Get status grid default cell color
   * const cellColor = themeManager.getDefault('statusGrid', 'defaultCellColor');
   * // Returns: 'var(--lcars-orange, #FF9900)' (resolved from token path)
   */
  getDefault(componentType, property, fallback = null, context = {}) {
    if (!this.resolver) {
      lcardsLog.warn('[ThemeManager] No resolver available - theme not initialized');
      return fallback;
    }

    const tokenPath = `components.${componentType}.${property}`;
    return this.resolver.resolve(tokenPath, fallback, context);
  }

  /**
   * Get component-scoped resolver function
   *
   * Returns a function that automatically prefixes token paths with component name.
   *
   * @param {string} componentType - Component type (e.g., 'statusGrid', 'overlayRenderer')
   * @returns {Function} Scoped resolver function
   * @throws {Error} If ThemeManager not initialized
   *
   * @example
   * const statusGridResolver = themeManager.getComponentResolver('statusGrid');
   * const cellColor = statusGridResolver('defaultCellColor', '#FF9900');
   * // Resolves: components.statusGrid.defaultCellColor
   */
  getComponentResolver(componentType) {
    if (!this.resolver) {
      throw new Error('ThemeManager not initialized - call initialize() first');
    }

    return (property, fallback = null, context = {}) => {
      const tokenPath = `components.${componentType}.${property}`;
      return this.resolver.resolve(tokenPath, fallback, context);
    };
  }

  /**
   * Get a theme token by path (for StylePresetManager integration)
   *
   * @param {string} tokenPath - Token path (e.g., 'colors.accent.primary')
   * @param {*} fallback - Fallback value if token not found
   * @param {Object} context - Additional context for resolution
   * @returns {*} Resolved token value or fallback
   *
   * @example
   * const primaryColor = themeManager.getToken('colors.accent.primary');
   * const textSize = themeManager.getToken('typography.fontSize.base', '16px');
   */
  getToken(tokenPath, fallback = undefined, context = {}) {
    if (!this.resolver) {
      lcardsLog.warn('[ThemeManager] No resolver available - theme not initialized');
      return fallback;
    }

    return this.resolver.resolve(tokenPath, fallback, context);
  }  /**
   * Get token resolver for direct token path resolution
   *
   * For advanced usage where you need direct access to the token resolver.
   *
   * @returns {ThemeTokenResolver} Token resolver instance
   * @throws {Error} If ThemeManager not initialized
   *
   * @example
   * const resolver = themeManager.getResolver();
   * const color = resolver.resolve('colors.accent.primary');
   */
  getResolver() {
    if (!this.resolver) {
      throw new Error('ThemeManager not initialized - call initialize() first');
    }
    return this.resolver;
  }

  /**
   * Get active theme information
   *
   * @returns {Object|null} Active theme info or null if not initialized
   *
   * @example
   * const theme = themeManager.getActiveTheme();
   * console.log(theme.name); // "LCARS Classic"
   * console.log(theme.tokens.components.chart); // {strokeColor: '...', ...}
   */
  getActiveTheme() {
    if (!this.activeTheme) {
      return null;
    }

    return {
      id: this.activeThemeId,
      name: this.activeTheme.name,
      description: this.activeTheme.description,
      packId: this.activeTheme.packId,
      tokens: this.activeTheme.tokens,  // ✅ NEW: Include actual tokens
      // ✅ NEW: Also include flattened token structure for direct access
      ...this.activeTheme.tokens  // This spreads colors, typography, components, etc. to top level
    };
  }

  /**
   * List all available theme IDs
   *
   * @returns {Array<string>} Array of theme IDs
   *
   * @example
   * const themes = themeManager.listThemes();
   * // Returns: ['lcards-default', 'lcars-ds9', 'lcars-voyager']
   */
  listThemes() {
    return Array.from(this.themes.keys());
  }

  /**
   * Get detailed theme information
   *
   * @param {string} themeId - Theme ID
   * @returns {Object|null} Theme details or null if not found
   *
   * @example
   * const themeInfo = themeManager.getTheme('lcards-default');
   * console.log(themeInfo.name); // "LCARS Classic"
   * console.log(themeInfo.packId); // "builtin_themes"
   */
  getTheme(themeId) {
    const theme = this.themes.get(themeId);
    return theme ? {
      id: themeId,
      name: theme.name,
      description: theme.description,
      packId: theme.packId,
      hasCssFile: !!theme.cssFile
    } : null;
  }

  /**
   * Count total tokens in theme
   *
   * @private
   * @param {Object} tokens - Token object
   * @returns {number} Total token count
   */
  _countTokens(tokens) {
    let count = 0;

    function countRecursive(obj) {
      for (const key in obj) {
        if (typeof obj[key] === 'object' && !Array.isArray(obj[key])) {
          countRecursive(obj[key]);
        } else {
          count++;
        }
      }
    }

    countRecursive(tokens);
    return count;
  }

  /**
   * Get debug information
   *
   * @returns {Object} Debug info including themes, active theme, and cache stats
   */
  getDebugInfo() {
    return {
      initialized: this.initialized,
      activeTheme: this.getActiveTheme(),
      availableThemes: this.listThemes().map(id => this.getTheme(id)),
      resolverCacheSize: this.resolver?.resolutionCache?.size || 0,
      themeCount: this.themes.size
    };
  }

  /**
   * Get all registered theme IDs
   * Used by Pack Explorer to list available themes
   * @returns {string[]} Array of theme IDs
   */
  getThemeIds() {
    return this.listThemes();
  }

  /**
   * Get theme metadata for Pack Explorer
   * @param {string} id - Theme ID
   * @returns {Object} Metadata object with id, name, description, version, pack
   */
  getThemeMetadata(id) {
    const theme = this.themes.get(id);
    if (!theme) {
      return null;
    }

    return {
      id,
      name: theme.name || id,
      description: theme.description || `${theme.name || id} theme`,
      version: theme.version || '1.0.0',
      pack: theme.packId || 'builtin_themes',
      type: 'theme',
      tokenCount: this._countTokens(theme.tokens || {}),
      hasCssFile: !!theme.cssFile
    };
  }

  /**
   * Get all themes with their metadata
   * Used by Pack Explorer to build tree view
   * @returns {Array<Object>} Array of theme metadata objects
   */
  getThemesWithMetadata() {
    return this.listThemes().map(id => this.getThemeMetadata(id)).filter(Boolean);
  }

  /**
   * Get themes by pack ID
   * Used by Pack Explorer to group themes by pack
   * @param {string} packId - Pack ID to filter by
   * @returns {Array<Object>} Array of theme metadata for the specified pack
   */
  getThemesByPack(packId) {
    return this.getThemesWithMetadata().filter(theme => theme.pack === packId);
  }

  /**
   * Clear all caches
   *
   * Useful for development/hot-reload scenarios.
   */
  clearCache() {
    if (this.resolver) {
      this.resolver.clearCache();
      lcardsLog.debug('[ThemeManager] Resolver cache cleared');
    }
  }

  /**
   * Track theme token resolution (for provenance tracking)
   *
   * Records token resolution chains for debugging and troubleshooting.
   * Called by cards when they resolve theme tokens through getToken() or getDefault().
   *
   * @param {string} tokenPath - Token path (e.g., 'colors.accent.primary')
   * @param {string} originalRef - Original reference (e.g., 'theme:colors.accent.primary')
   * @param {any} resolvedValue - Final resolved value
   * @param {Array<Object>} resolutionChain - Resolution steps
   * @param {Object} cardTracker - Card's ProvenanceTracker instance
   * @param {string[]} usedByFields - Fields using this token
   *
   * @example
   * themeManager.trackTokenResolution(
   *   'colors.accent.primary',
   *   'theme:colors.accent.primary',
   *   '#ff9966',
   *   [{ step: 'token_lookup', value: '#ff9966', source: 'theme.tokens' }],
   *   card._provenanceTracker,
   *   ['style.background']
   * );
   */
  trackTokenResolution(tokenPath, originalRef, resolvedValue, resolutionChain = [], cardTracker = null, usedByFields = []) {
    if (!cardTracker) {
      lcardsLog.trace('[ThemeManager] No card tracker provided for token resolution tracking');
      return;
    }

    // Build resolution chain if not provided
    if (resolutionChain.length === 0) {
      resolutionChain = [{
        step: 'token_lookup',
        value: resolvedValue,
        source: 'theme.tokens'
      }];
    }

    // Track in card's provenance tracker
    cardTracker.trackThemeToken(tokenPath, originalRef, resolvedValue, resolutionChain, usedByFields);

    lcardsLog.trace(`[ThemeManager] Tracked token resolution: ${tokenPath}`, {
      resolvedValue,
      usedByFields
    });
  }

  /**
   * Set alert mode
   *
   * Calls are serialized through _alertModeQueue (see constructor) so that
   * rapid successive calls always finish applying in the order they were
   * issued — otherwise an earlier call's async work could complete after a
   * later one's and clobber it, leaving the DOM/currentAlertMode stuck on a
   * stale mode.
   *
   * @param {string} mode - Alert mode ('red_alert', 'blue_alert', etc.)
   * @returns {Promise<void>}
   */
  setAlertMode(mode, opts = {}) {
    const run = () => this._applyAlertMode(mode, opts);
    const result = this._alertModeQueue.then(run, run);
    // Keep the queue alive even if this call's work throws — otherwise every
    // subsequent setAlertMode() call would chain onto a permanently-rejected
    // promise and never run. The rejection itself still propagates to whoever
    // awaits `result` (this call's own return value).
    this._alertModeQueue = result.then(() => undefined, () => undefined);
    return result;
  }

  /**
   * @param {string} mode
   * @param {Object} [opts]
   * @returns {Promise<void>}
   * @private
   */
  async _applyAlertMode(mode, opts = {}) {
    if (!ALERT_MODE_TRANSFORMS[mode]) {
      lcardsLog.warn(`[ThemeManager] Unknown alert mode: ${mode}`);
      return;
    }

    // Get HASS instance
    // @ts-ignore — _hass may be injected at runtime by ingestHass()
    const hass = this._hass || window.lcards?.core?._currentHass;
    if (!hass) {
      lcardsLog.error('[ThemeManager] Cannot set alert mode - HASS not available');
      return;
    }

    // Load user-customized transform parameters from persistent HA helpers (before injection)
    // Skip this when called from the Alert Lab editor, which has already set the live values
    // via setAlertModeTransformParameter() and does NOT want them overwritten by saved helpers.
    if (!opts.skipHelperLoad) {
      loadAlertTransformsFromHelpers(window.lcards?.core?.helperManager);
    }

    // Apply alert mode — opts.transitionStyle selects the visual transition effect
    await injectAlertMode(mode, hass, undefined, opts);

    // Update state
    this.currentAlertMode = mode;

    // Clear token cache (colors have changed)
    if (this.resolver) {
      this.resolver.clearCache();
    }

    // Invalidate LCARdSColorPicker CSS variable cache so freshly-opened
    // picker instances show the transformed swatch colours.
    try {
      const LCARdSColorPicker = /** @type {any} */ (customElements.get('lcards-color-picker'));
      if (LCARdSColorPicker?.invalidateCache) LCARdSColorPicker.invalidateCache();
    } catch (_) { /* safe to ignore */ }

    // Notify subscribers — everything is ready: CSS vars written, cache cleared,
    // currentAlertMode updated.  Safe for components to re-render immediately.
    if (this._alertModeSubscribers.size > 0) {
      this._alertModeSubscribers.forEach(cb => {
        try { cb(mode); } catch (e) {
          lcardsLog.warn('[ThemeManager] Alert mode subscriber threw:', e);
        }
      });
    }

    lcardsLog.info(`[ThemeManager] ✅ Alert mode: ${mode}`);
  }

  /**
   * Subscribe to alert mode changes.
   *
   * The callback is fired AFTER CSS variables have been written, the token
   * resolver cache has been cleared, and currentAlertMode has been updated.
   * This makes it safe to call requestUpdate() directly from the callback
   * without any additional deferral.
   *
   * @param {Function} callback - Called with (newMode: string)
   * @returns {Function} Unsubscribe function
   */
  subscribeToAlertMode(callback) {
    this._alertModeSubscribers.add(callback);
    lcardsLog.debug('[ThemeManager] Alert mode subscriber added');
    return () => {
      this._alertModeSubscribers.delete(callback);
      lcardsLog.debug('[ThemeManager] Alert mode subscriber removed');
    };
  }

  /**
   * Get current alert mode
   * @returns {string}
   */
  getAlertMode() {
    return this.currentAlertMode;
  }

  // ==========================================================================
  // TOKEN OVERRIDES — scoped per global / user / device
  // ==========================================================================

  /**
   * Subscribe to token override changes.
   *
   * The callback is fired after overrides are merged from all scopes and
   * applied to the resolver cache.  Safe to call requestUpdate() directly.
   *
   * @param {Function} callback - Called with no arguments on every change
   * @returns {Function} Unsubscribe function
   */
  subscribeToOverridesChanged(callback) {
    this._overrideSubscribers.add(callback);
    return () => this._overrideSubscribers.delete(callback);
  }

  /**
   * Notify all override subscribers and dispatch a window event so that
   * LCARdSCard base instances can call requestUpdate() cheaply.
   * Also invalidates the LCARdSColorPicker CSS variable cache so freshly-opened
   * pickers show the current values.
   * @private
   */
  _notifyOverridesChanged() {
    this._overrideSubscribers.forEach(cb => {
      try { cb(); } catch (e) {
        lcardsLog.warn('[ThemeManager] Override subscriber threw:', e);
      }
    });
    // Broadcast to all LCARdSCard base instances via a debounced window event.
    // Debouncing collapses rapid successive calls (e.g. dragging a token-override
    // slider) into a single dispatch, preventing N cards from each launching a
    // full async config re-process simultaneously.
    if (typeof window !== 'undefined') {
      if (this._overridesChangedTimer !== null) {
        clearTimeout(this._overridesChangedTimer);
      }
      this._overridesChangedTimer = setTimeout(() => {
        this._overridesChangedTimer = null;
        window.dispatchEvent(new CustomEvent('lcards:theme-overrides-changed'));
      }, 50);
    }
    // Invalidate LCARdSColorPicker static variable cache
    try {
      const LCARdSColorPicker = /** @type {any} */ (customElements.get('lcards-color-picker'));
      if (LCARdSColorPicker?.invalidateCache) LCARdSColorPicker.invalidateCache();
    } catch (_) { /* safe to ignore */ }
  }

  /**
   * Load and apply token overrides from all three scopes (global, user, device).
   * Device-scope values win when the same token path is set in multiple scopes.
   *
   * Safe to call at any time; no-ops gracefully when ScopedSettingsService is
   * unavailable (e.g. integration not loaded yet).
   *
   * @returns {Promise<void>}
   */
  async loadOverrides() {
    const sss = window.lcards?.core?.scopedSettingsService;
    if (!sss || !this.resolver) return;

    try {
      const allScopes = await sss.readAllScopes(STORAGE_KEY_THEME_OVERRIDES);
      // Merge: global first, user next, device last (device wins)
      const merged = {
        ...(allScopes.global  ?? {}),
        ...(allScopes.user    ?? {}),
        ...(allScopes.device  ?? {}),
      };
      this.resolver.setOverrides(Object.keys(merged).length ? merged : null);
      lcardsLog.info('[ThemeManager] Token overrides loaded', { count: Object.keys(merged).length });
    } catch (e) {
      lcardsLog.warn('[ThemeManager] Failed to load token overrides:', e);
      this.resolver.clearOverrides();
    }

    this._notifyOverridesChanged();
  }

  /**
   * Set a single token override for a given scope and persist it.
   *
   * @param {string} tokenPath - Dot-notation token path, e.g. 'colors.card.button'
   * @param {string|number} value - New value (CSS var, hex, or number)
   * @param {'global'|'user'|'device'} scope
   * @returns {Promise<void>}
   */
  async setOverride(tokenPath, value, scope) {
    const sss = window.lcards?.core?.scopedSettingsService;
    if (!sss) return;

    // Read the current overrides for this scope only so we deep-merge correctly
    const current = await sss.read(STORAGE_KEY_THEME_OVERRIDES, [scope]) ?? {};
    const updated = { ...current, [tokenPath]: value };
    await sss.write(STORAGE_KEY_THEME_OVERRIDES, updated, scope);
    lcardsLog.info(`[ThemeManager] Override set: ${tokenPath}=${value} (${scope})`);
    await this.loadOverrides();
  }

  /**
   * Remove a single token override from a scope.
   *
   * @param {string} tokenPath
   * @param {'global'|'user'|'device'} scope
   * @returns {Promise<void>}
   */
  async clearOverride(tokenPath, scope) {
    const sss = window.lcards?.core?.scopedSettingsService;
    if (!sss) return;

    const current = await sss.read(STORAGE_KEY_THEME_OVERRIDES, [scope]) ?? {};
    const updated = { ...current };
    delete updated[tokenPath];

    if (Object.keys(updated).length === 0) {
      await sss.clear(STORAGE_KEY_THEME_OVERRIDES, scope);
    } else {
      await sss.write(STORAGE_KEY_THEME_OVERRIDES, updated, scope);
    }

    lcardsLog.info(`[ThemeManager] Override cleared: ${tokenPath} (${scope})`);
    await this.loadOverrides();
  }

  /**
   * Returns the raw (un-overridden) resolved value for a token path.
   * Useful for showing "theme default" in the override editor UI.
   *
   * @param {string} tokenPath
   * @param {*} [fallback=null]
   * @returns {*}
   */
  getThemeDefault(tokenPath, fallback = null) {
    if (!this.resolver) return fallback;
    // Temporarily bypass by checking the token tree directly
    const savedOverrides = this.resolver._overrides;
    this.resolver._overrides = null;
    const value = this.resolver.resolve(tokenPath, fallback);
    this.resolver._overrides = savedOverrides;
    return value;
  }

  /**
   * Destroy theme manager and clean up resources
   */
  destroy() {
    this.themes.clear();
    this.activeThemeId = null;
    this.activeTheme = null;
    this.resolver = null;
    this.initialized = false;
    this._alertModeSubscribers.clear();
    this._overrideSubscribers.clear();

    lcardsLog.debug('[ThemeManager] Destroyed');
  }
}

// Make globally accessible for debugging
if (typeof window !== 'undefined') {
  window.ThemeManager = ThemeManager;
}